from __future__ import annotations

import argparse
from pathlib import Path

from ..core.paths import ROOT
OUT = ROOT / "docs" / "architecture" / "stage-registry.md"
HEADER = """# Stage registry — objective and determinism

<!-- GENERATED by `python -m pipeline.evidence.stage_doc` from pipeline/core/_stage_base.py:StageMeta.
     Do not edit by hand; edit the stage and regenerate. -->

Every stage declares the question it answers and whether it is reproducible. The contract those
two fields belong to is [`../research/artifact-contract.md`](../research/artifact-contract.md).

- **deterministic `true`** — same inputs and same params give byte-identical output.
- **deterministic `conditional`** — deterministic given the seed the stage records in its
  artifact's `_meta.params`; not otherwise.
- **deterministic `false`** — output varies between runs on identical inputs. Informs
  interpretation; does not pin a number.

"""
_MARK = {True: "sim", False: "**nao**", "conditional": "condicional"}


def render() -> str:
    from ..core import registry
    from .. import stages

    from ..core._stage_base import PHASE_ORDER, PHASE_QUESTION

    rows = sorted(registry.all_stages(), key=lambda s: s.meta.name)

    out = [HEADER, "## As fases, na ordem em que correm\n",
           "Cada stage declara a sua fase. Esta secção é derivada do registro, não escrita à "
           "mão — um stage novo aparece aqui sozinho.\n"]
    for phase in PHASE_ORDER:
        names = sorted(s.meta.name for s in rows if s.meta.phase == phase)
        if not names:
            continue
        out.append(f"**{phase}** — {PHASE_QUESTION[phase]}  \n"
                   + " · ".join(f"`{n}`" for n in names) + "\n")

    out += ["\n## Todos os stages\n",
            "| stage | fase | pergunta que responde | determinístico | depende de |",
            "|---|---|---|:-:|---|"]
    for s in rows:
        m = s.meta
        deps = ", ".join(f"`{d}`" for d in m.depends_on) or "—"
        out.append(f"| `{m.name}` | {m.phase} | {m.question or '—'} | "
                   f"{_MARK.get(m.deterministic, m.deterministic)} | {deps} |")

    nd = [s.meta for s in rows if s.meta.deterministic is not True]
    out.append("\n## Fontes de não-determinismo\n")
    out.append("| stage | determinístico | fonte |")
    out.append("|---|:-:|---|")
    for m in sorted(nd, key=lambda x: (x.deterministic is not False, x.name)):
        out.append(f"| `{m.name}` | {_MARK.get(m.deterministic, m.deterministic)} | "
                   f"{m.nondeterminism or '—'} |")

    n_det = sum(1 for s in rows if s.meta.deterministic is True)
    n_cond = sum(1 for s in rows if s.meta.deterministic == "conditional")
    out.append(f"\n{len(rows)} stages: {n_det} determinísticos, {n_cond} condicionais, "
               f"{len(rows) - n_det - n_cond} não-determinísticos.\n")
    return "\n".join(out)


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description="Render the stage registry to markdown.")
    ap.add_argument("--out", default=str(OUT))
    ap.add_argument("--check", action="store_true",
                    help="fail if the file on disk differs from the registry")
    args = ap.parse_args(argv)

    body = render()
    out = Path(args.out)
    if args.check:
        current = out.read_text(encoding="utf-8") if out.is_file() else ""
        if current != body:
            print(f"{out} is out of date with the stage registry. "
                  "Run `python -m pipeline.evidence.stage_doc`.")
            return 1
        print(f"{out} matches the registry")
        return 0

    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(body, encoding="utf-8")
    print(f"wrote {out}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
